/**********************************************************************************************************************
 Includes   <System Includes> , "Project Includes"
 *********************************************************************************************************************/
#include <stdint.h>

#ifndef OTFD_KEY_H_
#define OTFD_KEY_H_

/**********************************************************************************************************************
 Macro definitions
 *********************************************************************************************************************/
/** Encrypted key byte size **/
#define ENCRYPTED_KEY_BYTE_SIZE (48)

/**********************************************************************************************************************
 Global Typedef definitions
 *********************************************************************************************************************/
/** User key datas */
typedef struct encrypted_user_key_data
{
    uint32_t    keytype;
    uint32_t    shared_key_number;
    uint8_t     wufpk[32];
    uint8_t     initial_vector[16];
    uint8_t     encrypted_user_key[ENCRYPTED_KEY_BYTE_SIZE];
    uint8_t     crc[4];
} encrypted_user_key_data_t;

/**********************************************************************************************************************
 External global variables
 *********************************************************************************************************************/
extern const encrypted_user_key_data_t g_encrypted_user_key_data;

/**********************************************************************************************************************
 Exported global functions
 *********************************************************************************************************************/

#endif /* OTFD_KEY_H_ */
